<?php
if(!defined('ABSPATH')){exit;}
function ip_core_product_fields():void{echo '<div class="options_group">';woocommerce_wp_text_input(array('id'=>'_ip_book_subtitle','label'=>__('Book subtitle','illuminated-path-core')));woocommerce_wp_text_input(array('id'=>'_ip_isbn','label'=>__('ISBN','illuminated-path-core')));woocommerce_wp_text_input(array('id'=>'_ip_age_range','label'=>__('Age range','illuminated-path-core'),'placeholder'=>'5–8'));woocommerce_wp_text_input(array('id'=>'_ip_page_count','label'=>__('Page count','illuminated-path-core'),'type'=>'number','custom_attributes'=>array('min'=>'1','step'=>'1')));woocommerce_wp_text_input(array('id'=>'_ip_audio_url','label'=>__('Audio resource URL','illuminated-path-core'),'type'=>'url'));woocommerce_wp_text_input(array('id'=>'_ip_interactive_url','label'=>__('Purchased interactive activity URL','illuminated-path-core'),'type'=>'url','description'=>__('Buyers access it through My Account → Learning Library.','illuminated-path-core'),'desc_tip'=>true));woocommerce_wp_text_input(array('id'=>'_ip_course_url','label'=>__('Purchased course URL','illuminated-path-core'),'type'=>'url'));woocommerce_wp_textarea_input(array('id'=>'_ip_learning_objectives','label'=>__('Learning objectives','illuminated-path-core'),'description'=>__('One objective per line.','illuminated-path-core'),'desc_tip'=>true));echo '</div>';}add_action('woocommerce_product_options_general_product_data','ip_core_product_fields');
function ip_core_save_product_fields(WC_Product $product):void{foreach(array('_ip_book_subtitle','_ip_isbn','_ip_age_range') as $key){if(isset($_POST[$key])){$product->update_meta_data($key,sanitize_text_field(wp_unslash($_POST[$key])));}}if(isset($_POST['_ip_page_count'])){$product->update_meta_data('_ip_page_count',absint($_POST['_ip_page_count']));}foreach(array('_ip_audio_url','_ip_interactive_url','_ip_course_url') as $key){if(isset($_POST[$key])){$product->update_meta_data($key,esc_url_raw(wp_unslash($_POST[$key])));}}if(isset($_POST['_ip_learning_objectives'])){$product->update_meta_data('_ip_learning_objectives',sanitize_textarea_field(wp_unslash($_POST['_ip_learning_objectives'])));}}add_action('woocommerce_admin_process_product_object','ip_core_save_product_fields');
function ip_core_book_details_tab(array $tabs):array{global $product;if(!$product instanceof WC_Product){return $tabs;}foreach(array('_ip_book_subtitle','_ip_isbn','_ip_age_range','_ip_page_count','_ip_learning_objectives') as $key){if($product->get_meta($key)){$tabs['ip_book_details']=array('title'=>__('Book details','illuminated-path-core'),'priority'=>18,'callback'=>'ip_core_render_book_details');break;}}return $tabs;}add_filter('woocommerce_product_tabs','ip_core_book_details_tab');
function ip_core_render_book_details():void{global $product;if(!$product instanceof WC_Product){return;}$details=array(__('Subtitle','illuminated-path-core')=>$product->get_meta('_ip_book_subtitle'),__('Age range','illuminated-path-core')=>$product->get_meta('_ip_age_range'),__('Pages','illuminated-path-core')=>$product->get_meta('_ip_page_count'),__('ISBN','illuminated-path-core')=>$product->get_meta('_ip_isbn'));echo '<div class="ip-book-details"><dl>';foreach($details as $label=>$value){if(''!==(string)$value){echo '<div><dt>'.esc_html($label).'</dt><dd>'.esc_html((string)$value).'</dd></div>';}}echo '</dl>';$objectives=trim((string)$product->get_meta('_ip_learning_objectives'));if($objectives){echo '<h3>'.esc_html__('What children will explore','illuminated-path-core').'</h3><ul>';foreach(preg_split('/\r\n|\r|\n/',$objectives) as $objective){if(trim($objective)){echo '<li>'.esc_html(trim($objective)).'</li>';}}echo '</ul>';}echo '</div>';}
function ip_core_product_learning_note():void{global $product;if($product instanceof WC_Product&&($product->get_meta('_ip_interactive_url')||$product->get_meta('_ip_audio_url')||$product->get_meta('_ip_course_url'))){echo '<div class="ip-learning-note"><strong>'.esc_html__('Interactive learning included','illuminated-path-core').'</strong><p>'.esc_html__('After purchase, available resources appear securely in My Account → Learning Library.','illuminated-path-core').'</p></div>';}}add_action('woocommerce_single_product_summary','ip_core_product_learning_note',35);
